// A device package, as a firmware publishes its native modules: the host's probe (tools/erb-frames/host.c), whose
// interface and mock are in probe.ts and probe.mock.ts, and a radio that no host has, declared here.
// native-package.tsx imports both.
import {nativeModule} from 'embedded-react';
import type {Int} from 'embedded-react';
import type {Probe as ProbeInterface} from './probe';

export interface Radio {
  tune(channel: Int): boolean;
}

export const Probe = nativeModule<ProbeInterface>('probe', 1);
export const Radio = nativeModule.optional<Radio>('radio', 1);
